-- Confidence  : 0.60 (proposed)
-- Governance  : owner=Energy Data Engineering Team; classification=Internal - Restricted
-- Evidence    : clusters: OPS_006, OPS_008, OPS_017, OPS_020, OPS_025, OPS_026, OPS_029
