CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_OUTAGE_EVENT_DAY_REGION_CAUSE_CODE
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_OUTAGE_EVENT at grain Date.FiscalYear, Date.FullDate, Date.IsHoliday, Date.IsWeekend, Date.MonthName, Date.Quarter, Location.Region, OutageEvent.CauseCode, Date.MonthNumber; covers 84.45% of weighted demand (7 clusters); est. 550,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.FULL_DATE,
       d1.IS_HOLIDAY,
       d1.IS_WEEKEND,
       d1.MONTH_NAME,
       d1.QUARTER,
       l2.REGION,
       f.CAUSE_CODE,
       d1.MONTH_NUMBER,
       SUM(f.CUSTOMERS_AFFECTED) AS CUSTOMERS_AFFECTED,
       SUM(f.DURATION_MINUTES) AS DURATION_MINUTES,
       SUM(f.MAIFI_COUNT) AS MAIFI_COUNT,
       SUM(f.SAIDI_MINUTES) AS SAIDI_MINUTES,
       SUM(f.SAIFI_COUNT) AS SAIFI_COUNT,
       COUNT(*) AS OUTAGE_EVENT_COUNT
FROM CORE.FCT_OUTAGE_EVENT f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_LOCATION l2 ON f.LOCATION_ID = l2.LOCATION_ID
GROUP BY ALL;

-- Dynamic tables refresh with the owner's privileges: re-apply source policies on the aggregate.
ALTER DYNAMIC TABLE AGG.AGG_OUTAGE_EVENT_DAY_REGION_CAUSE_CODE ADD ROW ACCESS POLICY SEC.RAP_REGION ON (REGION);
